	}

	for _, b := range builtins {
		loaded, err := repo.GetByName(b.Name)
		if err != nil {
			t.Fatalf("GetByName(%q) error = %v", b.Name, err)
		}
		loaded.Bitrate = b.Bitrate + 1
		if err := repo.Update(loaded); err == nil {
